Compare the following two functionally equivalent C++ implementations and determine which one runs faster.

Here are two example comparisons with explanations:

### Example 1:

Code A:
```cpp


#include <iostream>

using namespace std;

int P[100001];

long long A[100001],B[100001],C[100001];

int D[100001];

int main() {

	int N,M;

	long long R=0;

	cin>>N>>M;

	for(int i=1;i<M+1;i++)cin>>P[i];

	for(int i=1;i<N;i++)cin>>A[i]>>B[i]>>C[i];

	for(int i=1;i<M;i++){

		if(P[i]<P[i+1]){

			for(int j=P[i];j<P[i+1];j++)D[j]+=1;

		}else{

			for(int j=P[i+1];j<P[i];j++)D[j]+=1;

		}

	}

	for(int j=1;j<N;j++)R+=min(D[j]*B[j]+C[j],D[j]*A[j]);

	cout<<R<<endl;

	return 0;

}
```

Code B:
```cpp
#include<cstdio>

#include<algorithm>

using namespace std;

const int MAX_N = 100000;

const int MAX_M = 100000;

int cnt[MAX_N+1];

int A[MAX_N],B[MAX_N],C[MAX_N];

int P[MAX_M];

int N,M;

int main(){

	scanf("%d%d",&N,&M);

	for(int i=0;i<M;i++){

		scanf("%d",P+i);

	}

	for(int i=0;i<N-1;i++){

		scanf("%d%d%d",A+i,B+i,C+i);

	}

	for(int i=0;i<M-1;i++){

		int x=P[i],y=P[i+1];

		if(x>y) swap(x,y);

		x--;

		y--;

		cnt[x]++;

		cnt[y]--;

	}

	for(int i=1;i<N;i++){

		cnt[i]+=cnt[i-1];

	}

	long long ans=0;

	for(int i=0;i<N-1;i++){

		long long paper=(long long)A[i]*cnt[i];

		long long ic=(long long)B[i]*cnt[i]+C[i];

		ans+=min(paper,ic);

	}

	printf("%lld\n",ans);

	return 0;

}


```

Code A increments every segment crossed between successive stops. Code B records two endpoint changes per trip and reconstructs segment counts in a separate pass. This avoids repeated segment visits on long trips, although the extra pass need not pay off on short trips. Their input/output paths also differ: A uses cin and cout without disabling stream synchronization, whereas B uses scanf and printf. The complete comparison therefore includes input/output costs as well as segment updates; the counting strategy alone does not guarantee the ordering for every input. Considering these implementations together, I select Code B.

**Answer: B**

